 proof fn always_double<T>(ex: Execution<T>, p: TempPred<T>)
     requires always(p).satisfied_by(ex),
     ensures always(always(p)).satisfied_by(ex),
 {
+    // Unfolding `always` reduces the goal to proving the relevant nested `forall`
+    // by using the given `always(p)` hypothesis.
+    assert(forall |i: nat| #[trigger] always(p).satisfied_by(ex.suffix(i)));
+    {
+        intro i: nat;
+        assert(always(p).satisfied_by(ex.suffix(i)));
+        {
+            // From `always(p).satisfied_by(ex)` we know that `p` holds at every suffix,
+            // so in particular it holds at `ex.suffix(i)`.
+            unfold always(p);
+            // After unfolding, the hypothesis gives: forall j, p.satisfied_by(ex.suffix(i + j)).
+            // We need: always(p).satisfied_by(ex.suffix(i)), i.e. forall j, p.satisfied_by((ex.suffix(i)).suffix(j)).
+            // Note that (ex.suffix(i)).suffix(j) == ex.suffix(i + j).
+            assert(forall |j: nat| #[trigger] p.satisfied_by(ex.suffix(i + j)));
+            {
+                // Directly use the unfolded hypothesis.
+                // The unfold above places us in a context where we can access the `forall`.
+            }
+        }
+        // Conclude the `always(p)` property at suffix i.
+    }
 }
*** End Patch

